# Load endpoint test data from pet.json
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / 'pet.json'
with open(_endpoint_data_path, 'r') as f:
    _ENDPOINT_DATA = json.load(f)

# Reusable parametrize args
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [case['scenario'] for case in _ENDPOINT_DATA]

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_update_pet(api_client, scenario_case, config_test_data):
    """
    Test updating an existing pet.
    """
    # Merge default test data with scenario specific data
    test_data = {**config_test_data, **scenario_case}

    # Ensure required fields are present
    if 'name' not in test_data or 'photoUrls' not in test_data:
        pytest.skip("Skipping test due to missing required fields")

    # Prepare request data
    request_data = {
        "name": test_data.get("name"),
        "photoUrls": test_data.get("photoUrls"),
        "id": test_data.get("id"),
        "category": test_data.get("category"),
        "tags": test_data.get("tags"),
        "status": test_data.get("status")
    }

    # Validate request schema
    schema_validator.validate_json(request_data, 'Pet')

    # Make the API call
    response = api_client.put('/pet', json=request_data)

    # Validate response status code
    assert response.status_code == test_data['statusCode'], f"Expected {test_data['statusCode']}, got {response.status_code}"

    # Validate response schema
    validation_result = schema_validator.validate_schema_by_response(
        '/pet', 'put', str(response.status_code), response
    )
    assert validation_result['valid'], f"Response validation failed: {validation_result['message']}"
